package li.cil.oc.plusplus;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static li.cil.oc.plusplus.OpticalDrivePlayback.*;
/** Drives the actual production coordinator, never a separate timing model. */
public class OpticalDrivePlaybackTest {
 static final class SinkLog implements Sink {
  final EnumMap<Channel,Sound> live=new EnumMap<>(Channel.class);final List<String> events=new ArrayList<>();int maximum;float gain,pitch;long audio=-1;
  public long audioTimeMicros(){return audio;}
  public void play(Channel c,Sound s,float g,float p,boolean loop){assertFalse(live.containsKey(c));assertEquals(s==Sound.LOOP,loop);assertEquals(1f,p,0);live.put(c,s);events.add("play:"+s);maximum=Math.max(maximum,live.size());}
  public void mix(Channel c,float g,float p){assertTrue(live.containsKey(c));gain=g;pitch=p;}
  public void stop(Channel c,Reason r){assertNotNull(live.remove(c));events.add("stop:"+c+":"+r);}
  int count(String e){return Collections.frequency(events,e);}
 }
 static final class Drive {
  final OpticalDrivePlayback p=new OpticalDrivePlayback();final SinkLog s=new SinkLog();long seq;
  boolean event(int action,long t){return p.accept(7,7,1,seq++,action,(int)Math.min(STARTUP_TICKS,t),t,true,s);}
  void through(long from,long to){for(long t=from;t<=to;t++){if(t%20==0)event(POWER,t);p.tick(t,true,s);}}
  void running(){assertTrue(event(POWER,0));through(1,STARTUP_TICKS);assertEquals(Phase.RUNNING,p.phase());}
 }
 @Test public void durationsCoverActualDecodedFramesWithoutLegacyFourSecondDelay(){assertEquals(51,STARTUP_TICKS);assertEquals(2510000L,startupMicros());assertEquals(3,SEEK_TICKS);assertEquals(46,STOP_TICKS);assertTrue(STARTUP_TICKS*2205L>=STARTUP_FRAMES);assertTrue((STARTUP_TICKS-1)*2205L<STARTUP_FRAMES);assertEquals(STOP_TICKS,FADE_TICKS);}
 @Test public void invalidDurationRejected(){try{ticksForFrames(0);fail();}catch(IllegalArgumentException expected){}}
 @Test public void startupOnceThenLoopLongBeyondClip(){Drive d=new Drive();d.event(POWER,0);d.through(1,1000);assertEquals(1,d.s.count("play:SPINUP"));assertEquals(1,d.s.count("play:LOOP"));assertEquals(Sound.LOOP,d.s.live.get(Channel.MOTOR));assertEquals(1,d.s.maximum);}
 @Test public void startupReadsCoalesceAndStartAfterLoop(){Drive d=new Drive();d.event(POWER,0);for(int t=1;t<STARTUP_TICKS;t++){if(t%20==0)d.event(POWER,t);d.event(SEEK,t);}assertTrue(d.p.pendingRead());assertEquals(0,d.s.count("play:SEEK"));d.event(POWER,STARTUP_TICKS);assertEquals(Arrays.asList("play:SPINUP","stop:MOTOR:REPLACED","play:LOOP","play:SEEK"),d.s.events);}
 @Test public void cueFinishesAndOnlyOneSuccessorQueues(){Drive d=new Drive();d.running();long t=STARTUP_TICKS+1;d.event(SEEK,t);for(long n=t+1;n<t+SEEK_TICKS;n++)d.event(SEEK,n);assertEquals(1,d.s.count("play:SEEK"));d.p.tick(t+SEEK_TICKS,true,d.s);assertEquals(2,d.s.count("play:SEEK"));d.p.tick(t+2*SEEK_TICKS,true,d.s);assertFalse(d.s.live.containsKey(Channel.TRANSIENT));assertEquals(2,d.s.maximum);}
 @Test public void heartbeatDoesNotRestartOrCutSeek(){Drive d=new Drive();d.running();long t=STARTUP_TICKS+1;d.event(SEEK,t);for(long n=t+1;n<t+SEEK_TICKS;n++)d.event(POWER,n);assertEquals(0,d.s.count("stop:TRANSIENT:COMPLETE"));d.p.tick(t+SEEK_TICKS,true,d.s);assertEquals(1,d.s.count("stop:TRANSIENT:COMPLETE"));assertEquals(1,d.s.count("play:LOOP"));}
 @Test public void naturalStopReplacesMotorOnceAtCurrentGainAndUnmodifiedPitch(){Drive d=new Drive();d.running();long t=STARTUP_TICKS+1;d.event(SEEK,t);d.event(STOP,t+1);assertEquals(Sound.SPINDOWN,d.s.live.get(Channel.MOTOR));assertEquals(.105f,d.p.gain(),.0001f);d.p.tick(t+20,true,d.s);assertEquals(.105f,d.p.gain(),.0001f);assertEquals(1f,d.p.pitch(),0);d.event(STOP,t+21);assertEquals(1,d.s.count("play:SPINDOWN"));d.p.tick(t+STOP_TICKS,true,d.s);assertEquals(Phase.FADING,d.p.phase());d.p.tick(t+1+STOP_TICKS,true,d.s);assertEquals(Phase.OFF,d.p.phase());assertTrue(d.s.live.isEmpty());assertEquals(1,d.s.count("stop:TRANSIENT:COMPLETE"));}
 @Test public void normalStopDoesNotCutAnInflightSeek(){Drive d=new Drive();d.running();long t=STARTUP_TICKS+1;d.event(SEEK,t);d.event(STOP,t+1);assertEquals(Sound.SEEK,d.s.live.get(Channel.TRANSIENT));d.p.tick(t+SEEK_TICKS-1,true,d.s);assertTrue(d.s.live.containsKey(Channel.TRANSIENT));d.p.tick(t+SEEK_TICKS,true,d.s);assertFalse(d.s.live.containsKey(Channel.TRANSIENT));assertEquals(0,d.s.count("stop:TRANSIENT:POWER_OFF"));}
 @Test public void stopWhileOffDoesNotInventCue(){Drive d=new Drive();d.event(STOP,0);assertTrue(d.s.events.isEmpty());}
 @Test public void readDuringStopCannotRestartOrQueue(){Drive d=new Drive();d.running();long t=STARTUP_TICKS+1;d.event(STOP,t);d.event(SEEK,t+1);assertFalse(d.p.pendingRead());d.p.tick(t+STOP_TICKS,true,d.s);d.event(SEEK,t+STOP_TICKS+1);assertTrue(d.s.live.isEmpty());assertFalse(d.p.pendingRead());}
 @Test public void readBeforePowerWaitsThroughStartup(){Drive d=new Drive();d.event(SEEK,0);assertTrue(d.s.live.isEmpty());d.event(POWER,1);d.through(2,1+STARTUP_TICKS);assertEquals(1,d.s.count("play:SEEK"));}
 @Test public void newGenerationRestartsOnceDuringRecordedStop(){Drive d=new Drive();d.running();long t=STARTUP_TICKS+1;d.event(STOP,t);assertTrue(d.p.accept(7,7,2,d.seq++,POWER,0,t+1,true,d.s));assertEquals(Sound.SPINUP,d.s.live.get(Channel.MOTOR));assertEquals(2,d.s.count("play:SPINUP"));assertEquals(1,d.s.count("play:SPINDOWN"));}
 @Test public void lateObserverBeginsSteadyLoopWithoutReplayingStartup(){Drive d=new Drive();d.event(POWER,STARTUP_TICKS);assertEquals(0,d.s.count("play:SPINUP"));assertEquals(1,d.s.count("play:LOOP"));}
 @Test public void ejectCancelsBothAndKeepsPreferredTray(){Drive d=new Drive();d.running();long t=STARTUP_TICKS+1;d.event(SEEK,t);d.event(OPEN,t+1);assertEquals(1,d.s.count("stop:MOTOR:EJECT"));assertEquals(1,d.s.count("stop:TRANSIENT:EJECT"));assertEquals(Sound.OPEN,d.s.live.get(Channel.TRANSIENT));d.p.tick(t+1+TRAY_TICKS,true,d.s);assertTrue(d.s.live.isEmpty());}
 @Test public void disconnectStopsRecordedStopImmediately(){Drive d=new Drive();d.running();long t=STARTUP_TICKS+1;d.event(STOP,t);d.event(CANCEL,t+1);assertTrue(d.s.live.isEmpty());assertEquals(1,d.s.count("stop:MOTOR:DISCONNECT"));}
 @Test public void staleMalformedPacketsHaveNoEffect(){Drive d=new Drive();d.event(POWER,0);int n=d.s.events.size();assertFalse(d.p.accept(7,8,1,10,POWER,0,1,true,d.s));assertFalse(d.p.accept(7,7,1,0,POWER,0,1,true,d.s));assertFalse(d.p.accept(7,7,0,10,POWER,0,1,true,d.s));assertFalse(d.p.accept(7,7,1,10,POWER,STARTUP_TICKS+1,1,true,d.s));assertFalse(d.p.accept(7,7,1,10,7,0,1,true,d.s));assertEquals(n,d.s.events.size());}
 @Test public void reloadUnloadMuteNeedFreshStateAndNeverReplaySeek(){for(Reason r:new Reason[]{Reason.RELOAD,Reason.UNLOAD,Reason.MUTED}){Drive d=new Drive();d.running();long t=STARTUP_TICKS+1;d.event(SEEK,t);d.p.reset(r,t+1,d.s);d.p.tick(t+2,true,d.s);assertTrue(d.s.live.isEmpty());assertFalse(d.p.accept(7,7,1,d.seq-1,POWER,STARTUP_TICKS,t+3,true,d.s));d.event(POWER,t+4);assertEquals(1,d.s.count("play:SPINUP"));assertEquals(2,d.s.count("play:LOOP"));assertEquals(1,d.s.count("play:SEEK"));}}
 @Test public void watchdogAndClockRollbackCancelImmediately(){Drive d=new Drive();d.event(POWER,0);d.p.tick(60,true,d.s);assertTrue(d.s.live.isEmpty());Drive e=new Drive();e.running();e.event(STOP,STARTUP_TICKS+1);e.p.tick(0,true,e.s);assertTrue(e.s.live.isEmpty());}
 @Test public void voiceBudgetBoundsEightDrivesAndSixteenHandles(){OpticalMotorVoices budget=new OpticalMotorVoices();List<Drive> drives=new ArrayList<>();for(int i=0;i<8;i++){assertTrue(budget.admit(i));Drive d=new Drive();d.running();d.event(SEEK,STARTUP_TICKS+1);drives.add(d);}assertFalse(budget.admit(8));assertEquals(16,drives.stream().mapToInt(d->d.s.live.size()).sum());drives.get(0).p.reset(Reason.UNLOAD,STARTUP_TICKS+2,drives.get(0).s);budget.release(0);assertTrue(budget.admit(8));}
 @Test public void legacyIdleStopStillCannotStopNewCoordinator(){assertEquals(SEEK,legacyEvent(OpticalSoundSchedule.READ));assertEquals(-1,legacyEvent(OpticalSoundSchedule.STOP));}

 static Drive nativeRunning(){Drive d=new Drive();d.s.audio=0;d.event(POWER,0);d.s.audio=startupMicros();d.through(1,STARTUP_TICKS);assertEquals(Phase.RUNNING,d.p.phase());d.p.audio(d.s);return d;}
 static long readMicros(){return ((long)SEEK_FRAMES*1000000+SAMPLE_RATE-1)/SAMPLE_RATE;}
 @Test public void frameDeadlineCompletesReadBeforeTheOldHalfSecondLease(){Drive d=nativeRunning();long t=d.s.audio;d.event(SEEK,STARTUP_TICKS+1);d.s.audio=t+readMicros()-1;d.p.audio(d.s);assertTrue(d.s.live.containsKey(Channel.TRANSIENT));d.s.audio++;d.p.audio(d.s);assertFalse(d.s.live.containsKey(Channel.TRANSIENT));assertEquals(1,d.s.count("stop:TRANSIENT:COMPLETE"));assertTrue(readMicros()<500000);assertEquals(1,d.s.count("play:LOOP"));}
 @Test public void pendingReadBeginsInSameSoftwareFrameAsCompletion(){Drive d=nativeRunning();long t=d.s.audio;d.event(SEEK,STARTUP_TICKS+1);d.s.audio=t+readMicros()/2;d.event(SEEK,STARTUP_TICKS+5);d.s.audio=t+readMicros();d.p.audio(d.s);assertEquals(2,d.s.count("play:SEEK"));assertEquals(Sound.SEEK,d.s.live.get(Channel.TRANSIENT));assertFalse(d.p.pendingRead());assertEquals(1,d.s.count("play:LOOP"));}
 @Test public void duckAttackHoldAndReleaseAreContinuousAndBounded(){Drive d=nativeRunning();long t=d.s.audio;d.event(SEEK,STARTUP_TICKS+1);assertEquals(.3f,d.p.gain(),.0001f);d.s.audio=t+25000;d.p.audio(d.s);assertEquals(.2025f,d.p.gain(),.0001f);d.s.audio=t+50000;d.p.audio(d.s);assertEquals(.105f,d.p.gain(),.0001f);d.s.audio=t+readMicros();d.p.audio(d.s);assertEquals(.105f,d.p.gain(),.0001f);d.s.audio=t+readMicros()+DUCK_HOLD_MICROS-1;d.p.audio(d.s);assertEquals(.105f,d.p.gain(),.0001f);d.s.audio=t+readMicros()+DUCK_HOLD_MICROS+75000;d.p.audio(d.s);assertEquals(.2025f,d.p.gain(),.0001f);d.s.audio+=75000;d.p.audio(d.s);assertEquals(.3f,d.p.gain(),.0001f);}
 @Test public void burstGapInsideHoldDoesNotPumpOrRestartMotor(){Drive d=nativeRunning();long t=d.s.audio;d.event(SEEK,STARTUP_TICKS+1);d.s.audio=t+50000;d.p.audio(d.s);d.s.audio=t+readMicros();d.p.audio(d.s);d.s.audio+=50000;d.event(SEEK,STARTUP_TICKS+12);assertEquals(.105f,d.p.gain(),.0001f);assertEquals(2,d.s.count("play:SEEK"));assertEquals(1,d.s.count("play:LOOP"));}
 @Test public void irregularDenseFramesKeepOnlyOnePendingReadAndTwoVoices(){Drive d=nativeRunning();long t=d.s.audio;int requests=0;for(long us=0;us<2200000;us+=16000){d.s.audio=t+us;long tick=STARTUP_TICKS+us/50000;if(us%48000==0){d.event(SEEK,tick);d.event(SEEK,tick);requests+=2;}if(us%160000==0)d.event(POWER,tick);d.p.audio(d.s);assertTrue(d.p.gain()>=.105f-.0001f&&d.p.gain()<=.3f+.0001f);assertTrue(d.s.live.size()<=2);}assertEquals(1,d.s.count("play:LOOP"));assertTrue(d.s.count("play:SEEK")<requests);assertEquals(2,d.s.maximum);}
 @Test public void readDuringReleaseAttacksFromCurrentGainWithoutJump(){Drive d=nativeRunning();long t=d.s.audio;d.event(SEEK,STARTUP_TICKS+1);d.s.audio=t+50000;d.p.audio(d.s);d.s.audio=t+readMicros()+DUCK_HOLD_MICROS+75000;d.p.audio(d.s);float before=d.p.gain();assertEquals(.2025f,before,.0001f);d.event(SEEK,STARTUP_TICKS+15);assertEquals(before,d.p.gain(),.0001f);d.s.audio+=25000;d.p.audio(d.s);assertTrue(d.p.gain()<before);}
 @Test public void softwareClockRollbackCancelsImmediately(){Drive d=nativeRunning();d.event(SEEK,STARTUP_TICKS+1);d.s.audio+=100000;d.p.audio(d.s);d.s.audio-=50000;d.p.audio(d.s);assertTrue(d.s.live.isEmpty());assertEquals(1,d.s.count("stop:MOTOR:CLOCK"));}
 @Test public void cancelDuringSoftwareCueAndHoldNeverReconstructsPlayback(){Drive d=nativeRunning();d.event(SEEK,STARTUP_TICKS+1);d.event(CANCEL,STARTUP_TICKS+2);d.s.audio+=1000000;d.p.audio(d.s);assertTrue(d.s.live.isEmpty());assertFalse(d.p.pendingRead());}
}
